    "visualizations": {
        "viz_4g1NeHsn": {
            "options": {
                "rx": 10,
                "strokeWidth": 0
            },
            "type": "splunk.rectangle"
        },
        "viz_C7d3gVTJ": {
            "options": {
                "fillColor": "#4c4f52",
                "fillOpacity": 0.7,
                "rx": 10,
                "strokeWidth": 0
            },
            "type": "splunk.rectangle"
        },
        "viz_E0o5fD4v": {
            "options": {
                "markdown": "### Numeric View\n\nUse Numeric View when you want to concentrate on the volume of entities that fall into different categories. "
            },
            "type": "splunk.markdown"
        },
        "viz_GYDCiUME": {
            "options": {
                "rx": 10,
                "strokeWidth": 0
            },
            "type": "splunk.rectangle"
        },
        "viz_H8RWrzR1": {
            "options": {
                "markdown": "### Legend Position\n\nYou can make the legend appear at the top, left, bottom, or right of the diagram - or hide it completely."
            },
            "type": "splunk.markdown"
        },
        "viz_Kz6q5LEg": {
            "options": {
                "markdown": "### Custom colors\n\nYou can set custom colors for the 3 categories, and choose to fill them or not."
            },
            "type": "splunk.markdown"
        },
        "viz_LCU1Avep": {
            "dataSources": {
                "primary": "ds_XO1ddpJ5"
            },
            "eventHandlers": [
                {
                    "options": {
                        "tokens": [
                            {
                                "key": "row.splFilter.value",
                                "token": "splFilter2"
                            }
                        ]
                    },
                    "type": "drilldown.setToken"
